import { setupServer } from 'msw/node';
import { handlers } from './handlers';

/**
 * Node-side MSW server for Vitest and Playwright's API-mocking runs (HO-CAT-002 §5.1). Import
 * and `server.listen()` / `server.resetHandlers()` / `server.close()` from a test setup file —
 * see web/tests/setup.ts.
 *
 * Browser-side mocking (`npm run dev` with NEXT_PUBLIC_USE_MOCKS=true) needs a service worker
 * script generated by `npx msw init public --save`, which no area has needed yet. Run that and
 * add a `mocks/browser.ts` (`setupWorker`) when the first area starts fetching real data.
 */
export const server = setupServer(...handlers);
